DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `populate_historical_actuals`()
BEGIN
    DECLARE team_counter INT DEFAULT 1;
    DECLARE curr_date DATE;  -- Changed from current_date
    DECLARE end_date DATE DEFAULT '2024-04-30';
    DECLARE base_headcount INT;
    DECLARE base_productivity DECIMAL(4,2);
    
    WHILE team_counter <= 22 DO
        SET curr_date = '2023-01-01';  -- Changed
        SET base_headcount = 15 + FLOOR(RAND() * 20);
        SET base_productivity = ROUND(2.5 + RAND() * 1.0, 1);
        
        WHILE curr_date <= end_date DO  -- Changed
            INSERT INTO actuals_data (
                team_id, period_date,
                headcount_pg1, headcount_pg2, headcount_pg3, headcount_pg4,
                headcount_pg5, headcount_pg6, headcount_pg7,
                daily_productivity,
