                95000 + (PERIOD_DIFF(DATE_FORMAT(curr_date, '%Y%m'), '202301') * 500) + RAND() * 20000,
                100000 + (PERIOD_DIFF(DATE_FORMAT(curr_date, '%Y%m'), '202301') * 500) + RAND() * 20000
            );
            
            SET curr_date = DATE_ADD(curr_date, INTERVAL 1 MONTH);  -- Changed
        END WHILE;
        
        SET team_counter = team_counter + 1;
    END WHILE;
